INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_homepage_module_user_ads_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select  T1.user_id
        ,T2.user_purchase_type
        ,T2.platform
        ,T2.app_version as version_sign
        ,T1.module
        ,T1.is_ads
        ,T1.imp_cnt
        ,T1.click_cnt
        ,T1.item_imp_cnt
        ,T1.item_click_cnt
        ,T1.ppv_cnt
        ,T1.order_cnt
        ,T1.gmv
        ,T1.pc2_gmv
        ,T1.hp_imp_cnt
        ,T1.hp_view_cnt
        ,if(T1.hp_is_scrolldown>0, 1, 0) as  hp_is_scrolldown
        ,T1.hp_scroll_depth
        ,T1.hp_duration
from    (
    select  user_id
            ,'__ALL__' as module
            ,'__ALL__' as is_ads
            ,sum(imp_cnt) as imp_cnt
            ,sum(click_cnt) as click_cnt
            ,sum(item_imp_cnt) as item_imp_cnt
            ,sum(item_click_cnt) as item_click_cnt
            ,sum(ppv_cnt) as ppv_cnt
            ,sum(order_cnt) as order_cnt
            ,sum(gmv) as gmv
            ,sum(pc2_gmv) as pc2_gmv
            ,sum(hp_imp_cnt) as hp_imp_cnt
            ,sum(hp_view_cnt) as hp_view_cnt
            ,1.000*sum(hp_duration)/1000 as hp_duration
            ,max(COALESCE(hp_is_scrolldown, 0)) as hp_is_scrolldown
            ,count(distinct if(imp_cnt>0  and module <>'Others' , module, null)) as hp_scroll_depth
    from    union_data_${grass_region_without_quote}
    group by 1
    union all
    select  user_id
            ,module
            ,is_ads
            ,sum(imp_cnt) as imp_cnt
            ,sum(click_cnt) as click_cnt
            ,sum(item_imp_cnt) as item_imp_cnt
            ,sum(item_click_cnt) as item_click_cnt
            ,sum(ppv_cnt) as ppv_cnt
            ,sum(order_cnt) as order_cnt
            ,sum(gmv) as gmv
            ,sum(pc2_gmv) as pc2_gmv
            ,0 hp_imp_cnt
            ,0 hp_view_cnt
            ,0 hp_duration
            ,0 hp_is_scrolldown
            ,0 hp_scroll_depth
    from    union_data_${grass_region_without_quote}
    group by 1 , 2, 3

    union all
    select  user_id
            ,'__LIVE_VIDEO_MERGE__' as module
            ,is_ads
            ,sum(imp_cnt) as imp_cnt
            ,sum(click_cnt) as click_cnt
            ,sum(item_imp_cnt) as item_imp_cnt
            ,sum(item_click_cnt) as item_click_cnt
            ,sum(ppv_cnt) as ppv_cnt
            ,sum(order_cnt) as order_cnt
            ,sum(gmv) as gmv
            ,sum(pc2_gmv) as pc2_gmv
            ,0 hp_imp_cnt
            ,0 hp_view_cnt
            ,0 hp_duration
            ,0 hp_is_scrolldown
            ,0 hp_scroll_depth
    from    union_data_${grass_region_without_quote}
    where module in ('Shopee Live Merge', 'Shopee Video Merge', 'Shopee Video&Live Merge See More')
    group by 1, 3

) as T1
left join dim_user_${grass_region_without_quote} as T2
on      T1.user_id = T2.user_id
;
